/**
 * Plain Kotlin state holder (no `@Composable` in its API) behind the Settings screen's display-unit
 * control and its workout-mode control ([sessionView], KAN-867) — two fields of one preferences
 * payload, each tracked by its own [OptimisticWrite]; everything below says about [unitWrite] and
 * [chooseUnit] holds unchanged for [viewWrite] and [chooseSessionView].
 *
 * The display-unit preference decides the unit a **newly created** workout is stamped with, and
 * nothing else: it rewrites no stored weight, converts nothing, and is not consulted by a workout
 * that already names a unit of its own. Writing it therefore invalidates no open screen — see
 * [com.gymie.shared.ui.workout.WorkoutEditorState.open] for the rule that makes that true.
 *
 * ### Reads and writes are tracked on independent sequences, never one shared revision
 *
 * [load] answers "what does the server hold", [chooseUnit] answers "did the server accept what I
 * just told it" — different questions. Conflating reads and writes into one shared revision counter
 * (this class's original design) is what let a stale write's *failure* discard a fresher read's true
 * answer, and separately let a stale read discard a fresher write's *confirmed success*. So each is
 * tracked against its own sequence — [load] via [loadSeq], [chooseUnit] via [unitWrite]'s internal
 * sequence — and the write keeps its own running count of the times it has actually *succeeded*
 * ([OptimisticWrite.succeededWriteCount]) — not just the newest call, every one, because even a write
 * whose own optimistic value later loses to a newer write still changed the server:
 *
 * - A **write**'s success always updates [unitWrite]'s confirmed value, even when a newer write has
 *   since superseded it — a write that later loses the screen to a newer one still changed the
 *   server, and a later failure must revert to what it actually confirmed, not to a value the server
 *   has since moved past. The visible [displayUnit] only follows along when its own write is still
 *   the newest one — independent of any load, in flight or not — which is also what lets a write's
 *   confirmed success stick on-screen even when an older, slower read resolves after it: the read is
 *   not consulted at all here.
 * - A **write**'s failure reverts [displayUnit] to its own confirmed value only when one exists.
 *   Before anything has ever been confirmed there is nothing honest to revert to, so the control is
 *   left showing the optimistic choice, the failure is still reported, and [loadFailed] is raised so
 *   the screen offers the same retry path a failed [load] does — see [OptimisticWrite.onFailure].
 * - A **load**'s success clears [loadFailed] only if it is still the newest load *and* no write has
 *   succeeded since this load began — a write already answered the question this load was asking, so
 *   a stale load's own answer is not news. [unitWrite]'s own confirmed/visible value updates
 *   independently through [OptimisticWrite.adoptLoad], gated on no write having succeeded since; the
 *   visible value additionally updates only while the write is not currently in flight, exactly as
 *   [OptimisticWrite.adoptLoad] itself already enforces. A *stale* success (superseded load, or a
 *   write has since succeeded) touches neither the confirmed nor visible value for the same reason a
 *   stale write's own response is not adopted elsewhere: the write that made it moot already answered
 *   the question.
 * - A **load**'s failure is gated exactly the same way its success's [loadFailed] clearing is: only
 *   while it is still the newest load *and* no write has succeeded since it began does it raise
 *   [loadFailed] and report a failure. A write's success already answered the question this load was
 *   asking, so a stale load's own failure to answer it is not news and must not undo that answer.
 *
 * [isLoading] and [isSaving] are reference counts — see their own docs — because [load] and
 * [chooseUnit] can each be called again before an earlier call of the *same* function has answered:
 * the screen launches a fresh coroutine per click, and [load] fires once at mount while the button is
 * already interactive. [chooseUnit]'s network sends are additionally serialised through [sendMutex]
 * so the server receives every write strictly in tap order.
 *
 * [isLoading], [isSaving] and [loadFailed] exist only so the screen can show progress and, after a
 * failed [load] (or a failed write with nothing yet confirmed), an in-place retry — none of the three
 * ever decides what [displayUnit] shows on its own.
 *
 * It takes [WorkoutCatalogApi] rather than the whole client because the preferences are the only
 * thing it touches; nothing here can reach a workout.
 */
class SettingsState(
    private val api: WorkoutCatalogApi,
    private val notifications: NotificationState,
) {
    /** Backs [displayUnit] and everything [load]/[chooseUnit] track about it. */
    private val unitWrite = OptimisticWrite(WeightUnit.KG)

    /** What the control shows. Kilograms until [load] has answered, matching the server's default. */
    val displayUnit: WeightUnit
        get() = unitWrite.value

    /** Backs [sessionView] and everything [load]/[chooseSessionView] track about it. */
    private val viewWrite = OptimisticWrite(SessionView.FOCUS)

    /** What the workout-mode control shows. Focus until [load] has answered, matching the server's default. */
    val sessionView: SessionView
        get() = viewWrite.value

    /** How many [load] calls are currently in flight; [isLoading] is true while this is positive. */
    private var loadingCalls: Int by mutableStateOf(0)

    /** True from the moment any [load] call starts until every overlapping one has answered. */
    val isLoading: Boolean
        get() = loadingCalls > 0

    /**
     * False until [load] has answered once, success or failure. The screen draws a skeleton until then:
     * [displayUnit] reads kilograms before the answer, and a user on pounds saw it flip (KAN-575 fix
     * round 4).
     */
    var hasLoaded: Boolean by mutableStateOf(false)
        private set

    /** True while at least one [chooseUnit] or [chooseSessionView] call is in flight. */
    val isSaving: Boolean
        get() = unitWrite.isSaving || viewWrite.isSaving

    /**
     * True once the latest [load] has failed, or the latest [chooseUnit] failed with nothing yet
     * confirmed to fall back on — either way the screen offers the same in-place retry, which is just
     * [load] again.
     */
    var loadFailed: Boolean by mutableStateOf(false)
        private set

    /** Advanced by every [load] call; a response is applied only while it is still the newest one. */
    private val loadSeq = Sequencer()

    /** Serialises every [chooseUnit] and [chooseSessionView] send — see the class KDoc. */
    private val sendMutex = Mutex()

    /** Reads the stored preferences, so the control opens on what the server actually holds. */
    suspend fun load() {
        val thisLoadSeq = loadSeq.next()
        val unitWritesBeforeThisLoad = unitWrite.succeededWriteCount
        val viewWritesBeforeThisLoad = viewWrite.succeededWriteCount
        loadingCalls++
        try {
            val result = runCatching { api.getPreferences() }
            // Computed once, right after the suspending call above returns and before either branch
            // below runs — there is no suspension point in between, so this cannot go stale by the
            // time either branch reads it. A write that succeeded after this load began already told
            // us the truth about the server, so this load's own answer — success *or* failure — is
            // stale and must not be treated as new information.
            val noUnitWriteSucceededSinceThisLoadBegan = unitWrite.succeededWriteCount == unitWritesBeforeThisLoad
            val noViewWriteSucceededSinceThisLoadBegan = viewWrite.succeededWriteCount == viewWritesBeforeThisLoad
            val current = loadSeq.isCurrent(thisLoadSeq)
            val noWriteSucceeded = noUnitWriteSucceededSinceThisLoadBegan && noViewWriteSucceededSinceThisLoadBegan
            result
                .onSuccess {
                    if (current && noWriteSucceeded) loadFailed = false
                    if (current && noUnitWriteSucceededSinceThisLoadBegan) unitWrite.adoptLoad(it.displayUnit)
                    if (current && noViewWriteSucceededSinceThisLoadBegan) viewWrite.adoptLoad(it.sessionView)
                }.onFailureNotCancelled {
                    if (current && noWriteSucceeded) {
                        loadFailed = true
                        notifications.failure(it.message ?: "Could not load your settings.")
                    }
                }
        } finally {
            loadingCalls--
            hasLoaded = true
        }
    }

    /**
     * Stores [unit] as the display preference, adopting whatever the server answers is now in
     * force, and putting the control back to its last confirmed value if the write is refused — see
     * the class KDoc for exactly when each of those happens.
     */
    suspend fun chooseUnit(unit: WeightUnit) {
        val token = unitWrite.begin(unit)
        try {
            runCatching { sendMutex.withLock { api.updatePreferences(displayUnit = unit) } }
                .onSuccess {
                    if (unitWrite.onSuccess(token, it.displayUnit)) loadFailed = false
                }.onFailureNotCancelled {
                    when (unitWrite.onFailure(token)) {
                        WriteFailureOutcome.STALE -> {
                            Unit
                        }

                        WriteFailureOutcome.REVERTED_TO_CONFIRMED -> {
                            notifications.failure(it.message ?: "Could not save your weight unit.")
                        }

                        WriteFailureOutcome.NOTHING_CONFIRMED -> {
                            // Nothing has ever been confirmed: reverting would invent a value the
                            // server never sent. Leave the control where it is and offer the same
                            // retry path a failed load does, so the user can re-sync.
                            loadFailed = true
                            notifications.failure(it.message ?: "Could not save your weight unit.")
                        }
                    }
                }
        } finally {
            unitWrite.end()
        }
    }

    /**
     * Stores [view] as the workout mode, exactly as [chooseUnit] stores the unit. The backend requires
     * `displayUnit` on every PUT, so this write carries the unit's last confirmed value — read inside
     * [sendMutex], once every earlier write has settled, so a unit choice still queued behind this
     * one never reaches the server through it. With nothing confirmed (a failed [load]) nothing is
     * sent: the write fails like a refused one. The answer's unit is not adopted: the unit's own
     * writes and loads own that field.
     */
    suspend fun chooseSessionView(view: SessionView) {
        val token = viewWrite.begin(view)
        try {
            runCatching {
                sendMutex.withLock {
                    // No confirmed unit (the load failed) means no honest value to send: the default
                    // would overwrite a stored LBS with KG. Refuse, and let the retry path re-sync.
                    val unit = unitWrite.confirmed ?: error("Could not save your workout mode.")
                    api.updatePreferences(displayUnit = unit, sessionView = view)
                }
            }.onSuccess {
                if (viewWrite.onSuccess(token, it.sessionView)) loadFailed = false
            }.onFailureNotCancelled {
                when (viewWrite.onFailure(token)) {
                    WriteFailureOutcome.STALE -> {
                        Unit
                    }

                    WriteFailureOutcome.REVERTED_TO_CONFIRMED -> {
                        notifications.failure(it.message ?: "Could not save your workout mode.")
                    }

                    WriteFailureOutcome.NOTHING_CONFIRMED -> {
                        loadFailed = true
                        notifications.failure(it.message ?: "Could not save your workout mode.")
                    }
                }
            }
        } finally {
            viewWrite.end()
        }
    }
}
