@Composable
fun SettingsScreen(
    api: GymieApiClient,
    notifications: NotificationState,
    // The shell's own store, passed down by `ShellDestinationContent` and read by the frame-rate row
    // alone (KAN-517 § 10); defaulted so the several desktopTests composing this screen directly are
    // left untouched.
    preferences: BooleanPreferences = remember { LocalPreferencesStore() },
) {
    BroadsheetTheme {
        val scope = rememberCoroutineScope()
        val settings = remember(api, notifications) { SettingsState(api, notifications) }
        LaunchedEffect(settings) { settings.load() }
        val profile = rememberProfileOrNull(api)
        val bodyUnits = remember(api, notifications) { BodyUnitState(api, notifications) }
        LaunchedEffect(profile) { profile?.let(bodyUnits::adopt) }
        Column(
            modifier =
                Modifier
                    .fillMaxSize()
                    .padding(BroadsheetTheme.space.space6)
                    .testTag("screen_settings"),
            // Frame A4's own 15dp internal gap between these rows, kept as they were. The 20dp
            // rhythm the outer Column used to apply between *groups* went with the groups.
            verticalArrangement = Arrangement.spacedBy(BroadsheetTheme.space.space3),
        ) {
            if (settings.hasLoaded) {
                DisplayUnitSetting(settings = settings, scope = scope)
                // The 1px neutral-300 rule frame A4 draws between the two rows. It sits *between* the
                // two settings rather than inside either, so it leaves `DisplayUnitSetting` and
                // `BodyUnitsSetting` themselves untouched.
                HorizontalDivider(
                    thickness = 1.dp,
                    color = BroadsheetTheme.colors.neutral300,
                    modifier = Modifier.testTag("settings_app_divider"),
                )
                // A shimmer row until the profile answers: the control is neither drawn greyed nor
                // selected on a default, then flipped (KAN-575 fix round 12).
                if (profile != null) {
                    BodyUnitsSetting(bodyUnits = bodyUnits, profile = profile, scope = scope)
                } else {
                    BroadsheetSkeleton(
                        width = 350.dp,
                        height = MIN_TOUCH_TARGET,
                        kind = BroadsheetSkeletonKind.Shimmer,
                        modifier = Modifier.testTag(BODY_UNITS_SKELETON_TAG),
                    )
                }
                HorizontalDivider(
                    thickness = 1.dp,
                    color = BroadsheetTheme.colors.neutral300,
                    modifier = Modifier.testTag("settings_session_view_divider"),
                )
                WorkoutModeSetting(settings = settings, scope = scope)
                // KAN-517 § 10 — draws nothing outside its own allow-list; see its own doc.
                ShowFrameRateSetting(profile = profile, preferences = preferences)
            } else {
                ScreenSkeleton()
            }
        }
    }
}

/**
 * Signs this device out, wherever the control that asked lives.
 *
 * KAN-189 task 10.3: the server scopes sign-out to whichever session presents its own refresh token
 * (task 10.2), so the client sends the one this device holds. **Clearing the local session is
 * unconditional** — a server that refuses the call (offline, already-consumed token) must not leave
 * the user stuck signed in.
 *
 * Its own function since KAN-573 task 3: the drawer's foot carries `Log out` now (`design.md` §4)
 * beside Settings' own button, and a second copy of this sequence is the one that would forget the
 * unconditional clear.
 */
internal suspend fun signOut(
    api: GymieApiClient,
    session: SessionStore,
    onLoggedOut: () -> Unit,
) {
    val refreshToken = session.refreshToken()
    runCatching { if (refreshToken != null) api.logout(RefreshRequest(refreshToken)) }
    session.clear()
    clearViewerHolders()
    onLoggedOut()
}

/** This screen's own focus-visible ring width — the same 2dp [WorkoutEditorScreen.kt]'s segmented-control chrome uses. */
private val SETTINGS_FOCUS_RING_WIDTH = 2.dp

/**
 * Chooses the unit **newly created** workouts are stamped with.
 *
 * It changes nothing about a workout that already exists: no stored weight is converted and no open
 * screen is invalidated, which is why nothing here bumps the shell's content refresh.
 */
@Composable
private fun DisplayUnitSetting(
    settings: SettingsState,
    scope: CoroutineScope,
) {
    val colors = BroadsheetTheme.colors
    Column(verticalArrangement = Arrangement.spacedBy(BroadsheetTheme.space.space1)) {
        // KAN-339 task 7: label and control now share one line — a Row rather than the stacked
        // Column this used to be. Everything below the row (state, progress line, disabled logic)
        // is unchanged.
        Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
            Column {
                Text("Weight unit", style = BroadsheetTheme.type.body, color = colors.text)
                Text("For sets in workouts", style = BroadsheetTheme.type.caption, color = colors.neutral700)
            }
            Spacer(modifier = Modifier.weight(1f))
            BroadsheetInlineSegmentedControl(
                options = WeightUnit.entries,
                selected = settings.displayUnit,
                label = WorkoutLabels::weightUnit,
                enabled = true,
                testTag = "settings_display_unit",
                optionTag = { "settings_display_unit_${it.name}" },
                onSelect = { option -> scope.launch { settings.chooseUnit(option) } },
            )
        }
        // **There is no progress line here, deliberately.** A `Working…` caption used to sit
        // between the control and the retry affordance. It is gone at the operator's explicit
        // instruction: a write to this screen is a single segmented-control tap that the control
        // itself already reflects — it disables while the write is in flight — so the caption
        // announced something the user could already see, and announced it on every tap.
        //
        // The height it used to reserve goes with it rather than being kept as an invisible
        // spacer: with nothing ever occupying that space, reserving it would be a gap no reader
        // could explain. `Log out` sits one caption-line higher than it used to, and stays put.
        if (settings.loadFailed) {
            val retryInteractionSource = remember { MutableInteractionSource() }
            val retryPressed by retryInteractionSource.collectIsPressedAsState()
            val retryFocused = retryInteractionSource.collectIsFocusVisible()
            val retryHovered by retryInteractionSource.collectIsHoveredAsState()
            val retryTextColor =
                when {
                    retryPressed -> colors.accent700
                    retryHovered -> colors.accent500
                    else -> colors.accent
                }
            TextButton(
                onClick = { scope.launch { settings.load() } },
                // Retry re-issues load() itself, so a second tap before the first answers is exactly
                // the overlapping-load call this button used to invite with no guard at all.
                enabled = !settings.isLoading,
                interactionSource = retryInteractionSource,
                modifier = Modifier.hoverable(retryInteractionSource).testTag("settings_display_unit_retry"),
            ) {
                Text(
